public void renderSwordEnergy(EntitySwordEnergy energyBall, double x, double y, double z, float rotationYaw, float partialTickTime) {
		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(energyBall.posX, energyBall.posY + 0.5D, energyBall.posZ, 
					2f,
					5.0f / 255.0f * 13.0F, 
					40.0f / 255.0f * 13.0F, 
					60.0f / 255.0f * 13.0F));
		}

		float ticks = energyBall.ticksExisted + partialTickTime;
		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y - 0.0625D - energyBall.pulseFloat, z);
		float f1 = ticks;
		bindTexture(FORCE_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float f2 = f1 * 0.01F;
		float f3 = f1 * 0.01F;
		GlStateManager.translate(f2, f3, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableBlend();
		float f4 = 0.5F;
		GlStateManager.color(f4, f4, f4, 1.0F);
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(SourceFactor.ONE, DestFactor.ONE);
		GlStateManager.scale(1F + energyBall.pulseFloat, 1F + energyBall.pulseFloat, 1F + energyBall.pulseFloat);
		model.render(0.0625F);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableLighting();
		GlStateManager.popMatrix();

		double interpPos1 = energyBall.lastPos1 + (energyBall.pos1 - energyBall.lastPos1) * partialTickTime;
		renderItemInBlock(x - interpPos1, y + 0.725F, z - interpPos1, this.swordPiece1, ticks);
		double interpPos2 = energyBall.lastPos2 + (energyBall.pos2 - energyBall.lastPos2) * partialTickTime;
		renderItemInBlock(x + interpPos2, y + 0.725F, z - interpPos2, this.swordPiece2, ticks);
		double interpPos3 = energyBall.lastPos3 + (energyBall.pos3 - energyBall.lastPos3) * partialTickTime;
		renderItemInBlock(x + interpPos3, y + 0.725F, z + interpPos3, this.swordPiece3, ticks);
		double interpPos4 = energyBall.lastPos4 + (energyBall.pos4 - energyBall.lastPos4) * partialTickTime;
		renderItemInBlock(x - interpPos4, y + 0.725F, z + interpPos4, this.swordPiece4, ticks);


		bindTexture(FORCE_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.translate(f2, 0, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableBlend();
		GlStateManager.color(f4, f4, f4, 1.0F);
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(SourceFactor.ONE, DestFactor.ONE);
		GlStateManager.enableTexture2D();
		GlStateManager.disableCull();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x - interpPos1 - 0.1F, y + 0.9F, z - interpPos1 - 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x - interpPos1, y - 0.14F, z - interpPos1);
		if(energyBall.pos1 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x + interpPos2 + 0.1F, y + 0.9F, z - interpPos2 - 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + interpPos2, y - 0.14F, z - interpPos2);
		if(energyBall.pos2 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x + interpPos3 + 0.1F, y + 0.9F, z + interpPos3 + 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + interpPos3, y - 0.14F, z + interpPos3);
		if(energyBall.pos3 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		renderBeam(new Vec3d(x, y + 0.85F, z), new Vec3d(x - interpPos4 - 0.1F, y + 0.9F, z + interpPos4 + 0.1F), 0.05F, 0.25F, true, true);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x - interpPos4, y - 0.14F, z + interpPos4);
		if(energyBall.pos4 < 3.5F)
			model.render(0.0625F);
		GlStateManager.popMatrix();
		GlStateManager.enableCull();
		GlStateManager.enableTexture2D();
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableLighting();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.disableBlend();
	}

public static void renderBeam(Vec3d start, Vec3d end, float startWidth, float endWidth, boolean renderStartCap, boolean renderEndCap) {
		Vec3d diff = start.subtract(end);
		Vec3d dir = diff.normalize();
		Vec3d upVec = new Vec3d(0, 1, 0);
		Vec3d localSide = dir.crossProduct(upVec).normalize();
		Vec3d localUp = localSide.crossProduct(dir).normalize();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vertexbuffer = tessellator.getBuffer();

		double maxVStart = diff.length() / 8.0D;
		double maxVEnd = diff.length() / 8.0D;
		double minVStart = 0.0D;
		double minVEnd = 0.0D;
		double maxU = diff.length() / 2.0D;

		vertexbuffer.begin(7, DefaultVertexFormats.POSITION_TEX);
		vertexbuffer.pos(start.x + (localSide.x + localUp.x) * startWidth, start.y + (localSide.y + localUp.y) * startWidth, start.z + (localSide.z + localUp.z) * startWidth).tex(0, minVStart).endVertex();
		vertexbuffer.pos(start.x + (localSide.x - localUp.x) * startWidth, start.y + (localSide.y - localUp.y) * startWidth, start.z + (localSide.z - localUp.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(end.x + (localSide.x - localUp.x) * endWidth, end.y + (localSide.y - localUp.y) * endWidth, end.z + (localSide.z - localUp.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(end.x + (localSide.x + localUp.x) * endWidth, end.y + (localSide.y + localUp.y) * endWidth, end.z + (localSide.z + localUp.z) * endWidth).tex(maxU, minVEnd).endVertex();

		vertexbuffer.pos(end.x + (-localSide.x + localUp.x) * endWidth, end.y + (-localSide.y + localUp.y) * endWidth, end.z + (-localSide.z + localUp.z) * endWidth).tex(maxU, minVEnd).endVertex();
		vertexbuffer.pos(end.x + (-localSide.x - localUp.x) * endWidth, end.y + (-localSide.y - localUp.y) * endWidth, end.z + (-localSide.z - localUp.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(start.x + (-localSide.x - localUp.x) * startWidth, start.y + (-localSide.y - localUp.y) * startWidth, start.z + (-localSide.z - localUp.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(start.x + (-localSide.x + localUp.x) * startWidth, start.y + (-localSide.y + localUp.y) * startWidth, start.z + (-localSide.z + localUp.z) * startWidth).tex(0, minVStart).endVertex();

		vertexbuffer.pos(end.x + (localUp.x + localSide.x) * endWidth, end.y + (localUp.y + localSide.y) * endWidth, end.z + (localUp.z + localSide.z) * endWidth).tex(maxU, minVEnd).endVertex();
		vertexbuffer.pos(end.x + (localUp.x - localSide.x) * endWidth, end.y + (localUp.y - localSide.y) * endWidth, end.z + (localUp.z - localSide.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(start.x + (localUp.x - localSide.x) * startWidth, start.y + (localUp.y - localSide.y) * startWidth, start.z + (localUp.z - localSide.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(start.x + (localUp.x + localSide.x) * startWidth, start.y + (localUp.y + localSide.y) * startWidth, start.z + (localUp.z + localSide.z) * startWidth).tex(0, minVStart).endVertex();

		vertexbuffer.pos(start.x + (-localUp.x + localSide.x) * startWidth, start.y + (-localUp.y + localSide.y) * startWidth, start.z + (-localUp.z + localSide.z) * startWidth).tex(0, minVStart).endVertex();
		vertexbuffer.pos(start.x + (-localUp.x - localSide.x) * startWidth, start.y + (-localUp.y - localSide.y) * startWidth, start.z + (-localUp.z - localSide.z) * startWidth).tex(0, maxVStart).endVertex();
		vertexbuffer.pos(end.x + (-localUp.x - localSide.x) * endWidth, end.y + (-localUp.y - localSide.y) * endWidth, end.z + (-localUp.z - localSide.z) * endWidth).tex(maxU, maxVEnd).endVertex();
		vertexbuffer.pos(end.x + (-localUp.x + localSide.x) * endWidth, end.y + (-localUp.y + localSide.y) * endWidth, end.z + (-localUp.z + localSide.z) * endWidth).tex(maxU, minVEnd).endVertex();

		if(renderStartCap) {
			vertexbuffer.pos(start.x + (localUp.x - localSide.x) * startWidth, start.y + (localUp.y - localSide.y) * startWidth, start.z + (localUp.z - localSide.z) * startWidth).tex(0, 1).endVertex();
			vertexbuffer.pos(start.x + (-localUp.x - localSide.x) * startWidth, start.y + (-localUp.y - localSide.y) * startWidth, start.z + (-localUp.z - localSide.z) * startWidth).tex(1, 1).endVertex();
			vertexbuffer.pos(start.x + (-localUp.x + localSide.x) * startWidth, start.y + (-localUp.y + localSide.y) * startWidth, start.z + (-localUp.z + localSide.z) * startWidth).tex(1, 0).endVertex();
			vertexbuffer.pos(start.x + (localUp.x + localSide.x) * startWidth, start.y + (localUp.y + localSide.y) * startWidth, start.z + (localUp.z + localSide.z) * startWidth).tex(0, 0).endVertex();
		}

		if(renderEndCap) {
			vertexbuffer.pos(end.x + (localUp.x + localSide.x) * endWidth, end.y + (localUp.y + localSide.y) * endWidth, end.z + (localUp.z + localSide.z) * endWidth).tex(0, 0).endVertex();
			vertexbuffer.pos(end.x + (-localUp.x + localSide.x) * endWidth, end.y + (-localUp.y + localSide.y) * endWidth, end.z + (-localUp.z + localSide.z) * endWidth).tex(1, 0).endVertex();
			vertexbuffer.pos(end.x + (-localUp.x - localSide.x) * endWidth, end.y + (-localUp.y - localSide.y) * endWidth, end.z + (-localUp.z - localSide.z) * endWidth).tex(1, 1).endVertex();
			vertexbuffer.pos(end.x + (localUp.x - localSide.x) * endWidth, end.y + (localUp.y - localSide.y) * endWidth, end.z + (localUp.z - localSide.z) * endWidth).tex(0, 1).endVertex();
		}
		tessellator.draw();
	}

public static void render(Player player, float partialTick, PoseStack poseStack, MultiBufferSource.BufferSource buffer) {
        Entity entity = MiscCapHelper.getClientTarget(player);
        if (entity instanceof LivingEntity livingentity) {
            int count = player.getUseItemRemainingTicks();
            int castTime = player.getUseItem().getUseDuration() - count;
            float f = getAttackAnimationScale(castTime, partialTick);
            float f1 = castTime + partialTick;
            float f2 = f1 * 0.5F % 1.0F;
            poseStack.pushPose();
            Vec3 targetPos = getPosition(livingentity, livingentity.getBbHeight() * 0.5, partialTick);
            Vec3 playerPos = player.getEyePosition(partialTick);
            if (Minecraft.getInstance().level != null) {
                boolean mainHand = WandUtil.getSpellOnHand(player, InteractionHand.MAIN_HAND) instanceof PrismaBeamSpell;
                ItemStack wand = mainHand ? player.getMainHandItem() : player.getOffhandItem();
                float staffHeight = wand.getItem() instanceof IWand w ? w.getWandVisualHeight(Minecraft.getInstance().level, player, wand) : 0.8F;
                if (player == Minecraft.getInstance().player && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON) {
                    // first-person staff end position
                    int arm = (player.getMainArm() == HumanoidArm.RIGHT ? 1 : -1) * (mainHand ? 1 : -1);
                    double fovFactor = 960.0 / (double) Minecraft.getInstance().options.fov().get();
                    float horizontalFactor = 0.125F * staffHeight + 0.35F, verticalFactor = 1.5F * staffHeight - 0.45F;
                    Vec3 vec3 = Minecraft.getInstance().gameRenderer.getMainCamera().getNearPlane().getPointOnPlane(horizontalFactor * arm, verticalFactor).scale(fovFactor);
                    playerPos = player.getEyePosition(partialTick).add(vec3);
                } else {
                    // third person staff end position
                    Optional<Vec3> staffEndPos = ModelUtil.getThirdPersonPlayerHandPosition(
                            player,
                            Minecraft.getInstance().getEntityRenderDispatcher(),
                            Mth.lerp(partialTick, player.yBodyRotO, player.yBodyRot),
                            partialTick,
                            mainHand ? player.getMainArm() : player.getMainArm().getOpposite(),
                            new Vec3(0, 0.55, -staffHeight)
                    );
                    if (staffEndPos.isPresent()) {
                        playerPos = staffEndPos.get();
                    }
                }
            }
            Vec3 view = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
            poseStack.translate(playerPos.x() - view.x(), playerPos.y() - view.y(), playerPos.z() - view.z());
            Vec3 diff = targetPos.subtract(playerPos);
            float f4 = (float) (diff.length() + 1.0D);
            diff = diff.normalize();
            float f5 = (float) Math.acos(diff.y);
            float f6 = (float) Math.atan2(diff.z, diff.x);
            poseStack.mulPose(Axis.YP.rotationDegrees((((float)Math.PI / 2F) - f6) * (180F / (float)Math.PI)));
            poseStack.mulPose(Axis.XP.rotationDegrees(f5 * (180F / (float)Math.PI)));
            float f7 = f1 * 0.05F * -1.5F;
            float f8 = f * f;
            int j = 64 + (int)(f8 * 191.0F);
            int k = 32 + (int)(f8 * 191.0F);
            int l = 128 - (int)(f8 * 64.0F);
            float f11 = Mth.cos(f7 + 2.3561945F) * 0.282F;
            float f12 = Mth.sin(f7 + 2.3561945F) * 0.282F;
            float f13 = Mth.cos(f7 + ((float)Math.PI / 4F)) * 0.282F;
            float f14 = Mth.sin(f7 + ((float)Math.PI / 4F)) * 0.282F;
            float f15 = Mth.cos(f7 + 3.926991F) * 0.282F;
            float f16 = Mth.sin(f7 + 3.926991F) * 0.282F;
            float f17 = Mth.cos(f7 + 5.4977875F) * 0.282F;
            float f18 = Mth.sin(f7 + 5.4977875F) * 0.282F;
            float f19 = Mth.cos(f7 + (float)Math.PI) * 0.2F;
            float f20 = Mth.sin(f7 + (float)Math.PI) * 0.2F;
            float f21 = Mth.cos(f7 + 0.0F) * 0.2F;
            float f22 = Mth.sin(f7 + 0.0F) * 0.2F;
            float f23 = Mth.cos(f7 + ((float)Math.PI / 2F)) * 0.2F;
            float f24 = Mth.sin(f7 + ((float)Math.PI / 2F)) * 0.2F;
            float f25 = Mth.cos(f7 + ((float)Math.PI * 1.5F)) * 0.2F;
            float f26 = Mth.sin(f7 + ((float)Math.PI * 1.5F)) * 0.2F;
            float f29 = -1.0F + f2;
            float f30 = f4 * 2.5F + f29;
            VertexConsumer vertexconsumer = buffer.getBuffer(BEAM_RENDER_TYPE);
            PoseStack.Pose posestack$pose = poseStack.last();
            Matrix4f matrix4f = posestack$pose.pose();
            Matrix3f matrix3f = posestack$pose.normal();
            vertex(vertexconsumer, matrix4f, matrix3f, f19, f4, f20, j, k, l, 0.4999F, f30);
            vertex(vertexconsumer, matrix4f, matrix3f, f19, 0.0F, f20, j, k, l, 0.4999F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f21, 0.0F, f22, j, k, l, 0.0F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f21, f4, f22, j, k, l, 0.0F, f30);
            vertex(vertexconsumer, matrix4f, matrix3f, f23, f4, f24, j, k, l, 0.4999F, f30);
            vertex(vertexconsumer, matrix4f, matrix3f, f23, 0.0F, f24, j, k, l, 0.4999F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f25, 0.0F, f26, j, k, l, 0.0F, f29);
            vertex(vertexconsumer, matrix4f, matrix3f, f25, f4, f26, j, k, l, 0.0F, f30);
            float f31 = 0.0F;
            if (player.tickCount % 2 == 0) {
                f31 = 0.5F;
            }

            vertex(vertexconsumer, matrix4f, matrix3f, f11, f4, f12, j, k, l, 0.5F, f31 + 0.5F);
            vertex(vertexconsumer, matrix4f, matrix3f, f13, f4, f14, j, k, l, 1.0F, f31 + 0.5F);
            vertex(vertexconsumer, matrix4f, matrix3f, f17, f4, f18, j, k, l, 1.0F, f31);
            vertex(vertexconsumer, matrix4f, matrix3f, f15, f4, f16, j, k, l, 0.5F, f31);
            poseStack.popPose();
            buffer.endBatch();
        }
    }

private Pair<BoltQuads, QuadCache> createQuads(QuadCache cache, Vec3 startPos, Vec3 end, float size) {
        Vec3 diff = end.subtract(startPos);
        Vec3 rightAdd = diff.cross(new Vec3(0.5, 0.5, 0.5)).normalize().scale(size);
        Vec3 backAdd = diff.cross(rightAdd).normalize().scale(size), rightAddSplit = rightAdd.scale(0.5F);

        Vec3 start = cache != null ? cache.prevEnd : startPos;
        Vec3 startRight = cache != null ? cache.prevEndRight : start.add(rightAdd);
        Vec3 startBack = cache != null ? cache.prevEndBack : start.add(rightAddSplit).add(backAdd);
        Vec3 endRight = end.add(rightAdd), endBack = end.add(rightAddSplit).add(backAdd);

        BoltQuads quads = new BoltQuads();
        quads.addQuad(start, end, endRight, startRight);
        quads.addQuad(startRight, endRight, end, start);

        quads.addQuad(startRight, endRight, endBack, startBack);
        quads.addQuad(startBack, endBack, endRight, startRight);

        return Pair.of(quads, new QuadCache(end, endRight, endBack));
    }

@Override
	public void handlePerspective(Key key, LivingEntity holder, ItemDisplayContext cameraItemDisplayContext, PoseStack mat)
	{
		if(holder==null||!holder.isUsingItem())
			return;
		boolean leftHand = cameraItemDisplayContext==FIRST_PERSON_LEFT_HAND||cameraItemDisplayContext==THIRD_PERSON_LEFT_HAND;
		boolean rightHand = cameraItemDisplayContext==FIRST_PERSON_RIGHT_HAND||cameraItemDisplayContext==THIRD_PERSON_RIGHT_HAND;
		if(!leftHand&&!rightHand)
			return;
		boolean leftIsMain = holder.getMainArm()==HumanoidArm.LEFT;
		InteractionHand inHand = (leftIsMain==leftHand)?InteractionHand.MAIN_HAND: InteractionHand.OFF_HAND;
		if(holder.getUsedItemHand()!=inHand)
			return;

		if(cameraItemDisplayContext==FIRST_PERSON_RIGHT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(-.15F, 0, 0));
			mat.translate(-.25, .5, -.4375);
		}
		else if(cameraItemDisplayContext==THIRD_PERSON_RIGHT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(0.52359F, 0, 0));
			mat.mulPose(new Quaternionf().rotateXYZ(0, 0.78539F, 0));
			mat.translate(.40625, -.125, -.125);
		}
		if(cameraItemDisplayContext==FIRST_PERSON_LEFT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(.15F, 0, 0));
			mat.translate(-.25, .375, .4375);
		}
		else if(cameraItemDisplayContext==THIRD_PERSON_LEFT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateX(-0.52359F).rotateY(-0.78539F));
			mat.translate(-.1875, .3125, .4375);
		}
	}

@Override
	public void render(Beam entity, float yaw, float tickDelta, PoseStack poseStack, MultiBufferSource vertices, int light) {
		LivingEntity caster = entity.getCaster();
		Vec3 cam = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();

		if(caster != null) {
			Vec3 startPos = caster.getPosition(tickDelta).add(0, caster.getEyeHeight(caster.getPose()) * 0.9f, 0);
			Vec3 endPos = entity.getBeamPos(tickDelta);
			Vector3d axis = new Vector3d(endPos.x() - startPos.x(), endPos.y() - startPos.y(), endPos.z() - startPos.z()).normalize();
			VertexConsumer vertex = vertices.getBuffer(LAYER);
			Color color = ArcanusHelper.getMagicColor(entity);
			float distance = entity.distanceTo(caster) / 2f;

			poseStack.pushPose();
			poseStack.translate(-entity.getX(), -entity.getY(), -entity.getZ());

			for(int i = 0; i < 2; i++) {
				Vector3d vec = new Vector3d(cam.x(), cam.y(), cam.z()).sub(startPos.x(), startPos.y(), startPos.z()).cross(axis).normalize().mul(0.2);
				vec.rotateAxis(Math.toRadians(i == 0 ? 45 : -45), axis.x, axis.y, axis.z);
				Vec3 vert1 = startPos.add(vec.x, vec.y, vec.z);
				Vec3 vert2 = startPos.subtract(vec.x, vec.y, vec.z);
				Vec3 vert3 = endPos.add(vec.x, vec.y, vec.z);
				Vec3 vert4 = endPos.subtract(vec.x, vec.y, vec.z);
				float beamProgress = entity.getBeamProgress(tickDelta) * 2f;

				if(i > 0)
					beamProgress *= -1f;

				float minU = 0;
				float minV = -beamProgress;
				float maxU = 1;
				float maxV = distance - beamProgress;

				if(i > 0) {
					minV = 1 - minV;
					maxV = 1 - maxV;
				}

				vertex(vertex, poseStack, vert4, color, maxU, minV);
				vertex(vertex, poseStack, vert3, color, minU, minV);
				vertex(vertex, poseStack, vert1, color, minU, maxV);
				vertex(vertex, poseStack, vert2, color, maxU, maxV);
			}

			poseStack.popPose();
		}
	}

@Override
	public void render(MagicRune entity, float yaw, float tickDelta, PoseStack poseStack, MultiBufferSource vertices, int light) {
		super.render(entity, yaw, tickDelta, poseStack, vertices, light);
		Color color = ArcanusHelper.getMagicColor(entity);
		float alpha = keyFrames[entity.tickCount % keyFrames.length] / 16f;
		float r = color.redF() * alpha;
		float g = color.greenF() * alpha;
		float b = color.blueF() * alpha;
		color = Color.fromFloatsRGB(r, g, b);

		poseStack.pushPose();
		poseStack.translate(0, Math.sin((entity.tickCount + tickDelta) * 0.125) * 0.05, 0);
		poseStack.mulPose(Axis.YP.rotationDegrees(entity.tickCount + tickDelta));
		model.renderToBuffer(poseStack, vertices.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color.asIntARGB());
		poseStack.popPose();
	}

@Override
	protected void draw(Tessellator tessellator, double length, float partialTicks){

		float scale = this.particleScale;

		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		GlStateManager.pushMatrix();
		// Enables texture tiling (Also used for guardian beam, beacon beam and ender crystal beam, amongst others)
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		GlStateManager.rotate(Minecraft.getMinecraft().player.ticksExisted + partialTicks, 0, 0, 1);

		Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		float t = THICKNESS * scale;
		float v1 = 2 * (particleAge + partialTicks) / particleMaxAge;
		float v2 = v1 + (float)length * 2; // Multiply by 2 to make it squished like it is in vanilla

		buffer.pos(-t, 0, 0)   .tex(0,   v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos( t, 0, 0)   .tex(0.5, v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos( t, 0, length).tex(0.5, v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(-t, 0, length).tex(0,   v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();

		buffer.pos(0, -t, 0)   .tex(0,   v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(0,  t, 0)   .tex(0.5, v1)  .color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(0,  t, length).tex(0.5, v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();
		buffer.pos(0, -t, length).tex(0,   v2).color(particleRed, particleGreen, particleBlue, 1).endVertex();

		tessellator.draw();

//		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
//		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		GlStateManager.popMatrix();

		// Makes the rain go weird
		//GlStateManager.enableLighting();
	}

@SubscribeEvent
	public static void onRenderWorldLastEvent(RenderWorldLastEvent event){
		// Only render in first person
		if(Minecraft.getMinecraft().gameSettings.thirdPersonView == 0){

			EntityPlayer player = Minecraft.getMinecraft().player;

			if(WizardData.get(player).getVariable(Shield.SHIELD_KEY) != null && EntityUtils.isCasting(player, Spells.shield)){

				GlStateManager.pushMatrix();

				GlStateManager.disableCull();
				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GL11.GL_ONE, GL11.GL_SRC_ALPHA);
				GlStateManager.shadeModel(GL11.GL_SMOOTH);
				GlStateManager.disableLighting();
				OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

				GlStateManager.translate(0, 1.4, 0);

				GlStateManager.rotate(-player.rotationYaw, 0, 1, 0);
				GlStateManager.rotate(player.rotationPitch, 1, 0, 0);

				GlStateManager.translate(0, 0, 1);

				GlStateManager.pushMatrix();

				// Changes the scale at which the texture is applied to the model. See LayerCreeper for a similar example,
				// but with translation instead of scaling.
				// You can do all sorts of fun stuff with this, just by applying transformations in the 2D texture space.
				GlStateManager.matrixMode(GL11.GL_TEXTURE); // Switch to the 2D texture space
				GlStateManager.loadIdentity();

				GlStateManager.translate(0.5, 0.5, 0);

				float s = 1 - ((player.ticksExisted + event.getPartialTicks()) % 5) / 5 * 0.52f;
				s = s*s;
				GlStateManager.scale(s, s, 1);

				GlStateManager.translate(-0.5, -0.5, 0);

				GlStateManager.matrixMode(GL11.GL_MODELVIEW); // Switch back to the 3D model space

				Tessellator tessellator = Tessellator.getInstance();

				Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

				render(tessellator);

				// Undo the texture scaling
				GlStateManager.matrixMode(GL11.GL_TEXTURE);
				GlStateManager.loadIdentity();
				GlStateManager.matrixMode(GL11.GL_MODELVIEW);

				GlStateManager.popMatrix();

				GlStateManager.enableLighting();

				GlStateManager.shadeModel(GL11.GL_FLAT);
				GlStateManager.enableCull();
				GlStateManager.disableBlend();
				// RenderHelper.enableStandardItemLighting();

				GlStateManager.popMatrix();
			}
		}
	}

private static void render(Tessellator tessellator){

		BufferBuilder buffer = tessellator.getBuffer();

		double widthOuter = 0.6d;
		double heightOuter = 0.7d;
		double widthInner = 0.3d;
		double heightInner = 0.4d;
		double depth = 0.2d;

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_TEX_COLOR);

		buffer.pos(-widthOuter, heightInner, -depth).tex(0, 0.2).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(-widthInner, heightOuter, -depth).tex(0.2, 0).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();

		buffer.pos(widthInner, heightOuter, -depth).tex(0.8, 0).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, heightInner, 0).tex(0.8, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthOuter, heightInner, -depth).tex(1, 0.2).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, heightInner, 0).tex(0.8, 0.2).color(200, 200, 255, 255).endVertex();

		buffer.pos(widthOuter, -heightInner, -depth).tex(1, 0.8).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, -heightInner, 0).tex(0.8, 0.8).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthInner, -heightOuter, -depth).tex(0.8, 1).color(0, 0, 0, 255).endVertex();
		buffer.pos(widthInner, -heightInner, 0).tex(0.8, 0.8).color(200, 200, 255, 255).endVertex();

		buffer.pos(-widthInner, -heightOuter, -depth).tex(0.2, 1).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, -heightInner, 0).tex(0.2, 0.8).color(200, 200, 255, 255).endVertex();
		buffer.pos(-widthOuter, -heightInner, -depth).tex(0, 0.8).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, -heightInner, 0).tex(0.2, 0.8).color(200, 200, 255, 255).endVertex();

		buffer.pos(-widthOuter, heightInner, -depth).tex(0, 0.2).color(0, 0, 0, 255).endVertex();
		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();

		tessellator.draw();

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_TEX_COLOR);

		buffer.pos(-widthInner, heightInner, 0).tex(0.2, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthInner, heightInner, 0).tex(0.8, 0.2).color(200, 200, 255, 255).endVertex();
		buffer.pos(-widthInner, -heightInner, 0).tex(0.2, 0.8).color(200, 200, 255, 255).endVertex();
		buffer.pos(widthInner, -heightInner, 0).tex(0.8, 0.8).color(200, 200, 255, 255).endVertex();

		tessellator.draw();
	}

@Override
	public void doRender(EntityMagicConstruct entity, double x, double y, double z, float entityYaw, float partialTicks){

		// Makes the sigil invisible to enemies of the player that created it
		if(this.invisibleToEnemies){
			// Unfortunately we can't access the caster's allies if they're not online, it only works the other way round
			if(entity.getCaster() != Minecraft.getMinecraft().player && entity.getCaster() instanceof EntityPlayer
					&& !AllyDesignationSystem.isPlayerAlly((EntityPlayer)entity.getCaster(), Minecraft.getMinecraft().player)){
				return;
			}
		}

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240, 240);
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		float yOffset = 0;

		GlStateManager.translate((float)x, (float)y + yOffset, (float)z);

		this.bindTexture(texture);
		float f6 = 1.0F;
		float f7 = 0.5F;
		float f8 = 0.5F;

		GlStateManager.rotate(-90, 1, 0, 0);

		// Healing aura rotates slowly
		if(rotationSpeed != 0) GlStateManager.rotate(entity.ticksExisted * rotationSpeed, 0, 0, 1);

		float s = entity.width * DrawingUtils.smoothScaleFactor(entity.lifetime, entity.ticksExisted, partialTicks, 10, 10);
		GlStateManager.scale(s, s, s);

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();
		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

		buffer.pos(0.0F - f7, 0.0F - f8, 0.01).tex(0, 1).endVertex();
		buffer.pos(f6   - f7, 0.0F - f8, 0.01).tex(1, 1).endVertex();
		buffer.pos(f6   - f7, 1.0F - f8, 0.01).tex(1, 0).endVertex();
		buffer.pos(0.0F - f7, 1.0F - f8, 0.01).tex(0, 0).endVertex();

		tessellator.draw();

		GlStateManager.disableBlend();
		GlStateManager.enableLighting();
		GlStateManager.disableRescaleNormal();
		GlStateManager.popMatrix();
	}
